export default async function install(app){const style=document.createElement('style');style.id='prowise-footer-center-icon-box';style.textContent='#prowise-tools-center{top:50%!important;transform:translate(-50%,-50%)!important;background:#dde3e8;padding:6px;border-radius:16px;gap:8px;box-sizing:border-box}';document.head.append(style);app.onCleanup(()=>style.remove());await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const group=document.getElementById('prowise-tools-center');const mount=document.getElementById('app-mount-map-bottom-space');if(!group||!mount)throw new Error('Footer mount or sketch/measure group missing');const f=mount.getBoundingClientRect(),g=group.getBoundingClientRect();return {groupPresent:true,icons:group.querySelectorAll('button').length,footerHeight:f.height,groupHeight:g.height,topInset:g.top-f.top,bottomInset:f.bottom-g.bottom,verticalCenterError:(g.top+g.bottom-f.top-f.bottom)/2,color:getComputedStyle(group).backgroundColor}}